<script setup lang="ts">
import {ref,reactive,computed,watch} from 'vue'
import {onShow,onLoad} from '@dcloudio/uni-app'
import WorkspaceShell from '../../components/WorkspaceShell.vue'
import AppIcon from '../../components/AppIcon.vue'
import AdcField from '../../components/AdcField.vue'
import DoctorCalendar from './DoctorCalendar.vue'
import {request,uuid,format} from '../../api'
import {work,resources,requireWorkspace,loadWorkspace,dayLabel,clock,localDay,clinicName,doctorName,goCase,type Row} from '../../workspace'
const filter=ref('published'),date=ref(''),selected=ref<Row|null>(null),original=ref<Row|null>(null),draft=ref<Row|null>(null),preview=ref<Row|null>(null),busy=ref(false),error=ref(''),notice=ref(''),editor=ref(''),dirty=ref(false),stopReason=ref(''),initialId=ref(0)
let nativeTop=0
// #ifdef MP-WEIXIN
nativeTop=Math.max(uni.getSystemInfoSync().statusBarHeight||0,uni.getMenuButtonBoundingClientRect().bottom||0)+12
// #endif
const nativeInsetStyle:Record<string,string>=nativeTop?{paddingTop:nativeTop+'px',boxSizing:'border-box'}:{}
const calendarChoices=ref<Row[]>([])
let calendarRequest=0
const proposal=reactive<Row>({clinic_id:'',dentist_id:'',calendar_id:'',starts_at:'',ends_at:'',qualification_kind_ids:[]}),decisions=reactive<Record<string,Row>>({})
const travel=reactive<Row>({from_clinic_id:'',to_clinic_id:'',minimum_minutes:45,valid_from:localDay(),confirmation_basis:''})
let requestKey='',requestBody=''
const duties=computed(()=>(resources.value.duties||[]).filter(d=>(filter.value==='all'||filter.value==='drafts'?filter.value==='all'||['draft','pending_coordination'].includes(d.publication_state):d.publication_state===filter.value)&&(!date.value||localDay(d.starts_at)===date.value)))
const formResources=computed(()=>{
 const items=new Map(calendarChoices.value.map(c=>[c.id,c]))
 for(const c of resources.value.calendars||[]){
  if(c.clinic_id===proposal.clinic_id&&c.is_open&&!items.has(c.id))items.set(c.id,c)
 }
 return {...resources.value,calendars:[...items.values()].sort((a,b)=>a.starts_at.localeCompare(b.starts_at))}
})
const operatories=computed(()=>(resources.value.operatories||[]).filter(o=>o.clinic_id===proposal.clinic_id&&o.resource_state==='active'))
const fields=[{key:'clinic_id',label:'接诊门店',type:'select:clinics',required:true},{key:'dentist_id',label:'接诊牙医',type:'select:dentists',required:true},{key:'calendar_id',label:'已确认营业日历',type:'select:calendars',required:true},{key:'starts_at',label:'完整出诊开始',type:'datetime',required:true},{key:'ends_at',label:'完整出诊结束',type:'datetime',required:true},{key:'qualification_kind_ids',label:'出诊所需资格',type:'multi:qualification_kinds',required:false}]
const scheduleView=ref<'week'|'roster'|'records'>('week')
const calendarRevision=ref(0),initialClinic=ref(0),initialCross=ref(false)
let initialAction=''
onLoad((q:any)=>{initialId.value=Number(q?.id||0);initialAction=q?.action||'';initialClinic.value=Number(q?.clinic||0);initialCross.value=q?.view==='cross';if(q?.view==='roster')scheduleView.value='roster';if(initialId.value)scheduleView.value='records'})
onShow(async()=>{
 if(!await requireWorkspace('UC09'))return
 calendarRevision.value++
 if(initialId.value){await inspect(initialId.value);initialId.value=0}
 if(initialAction==='draft'){initialAction='';await startEdit()}
})
watch(proposal,()=>{dirty.value=true;preview.value=null},{deep:true,flush:'sync'})
watch(()=>proposal.clinic_id,async clinic=>{
 const seq=++calendarRequest
 const previous=[...calendarChoices.value,...(resources.value.calendars||[])].find(c=>c.id===proposal.calendar_id)
 if(previous&&previous.clinic_id!==clinic)proposal.calendar_id=''
 calendarChoices.value=[]
 if(!clinic)return
 try {
  const response=await request('/api/clinics/'+clinic+'/calendar-options')
  if(seq===calendarRequest)calendarChoices.value=response.calendars.map((c:Row)=>({...c,label:clinicName(c.clinic_id)+' · '+c.work_date+' · 时段'+c.session_no}))
 } catch(problem:any){if(seq===calendarRequest)error.value=problem.message}
})
watch(()=>proposal.calendar_id,id=>{const cal=formResources.value.calendars.find(c=>c.id===id);if(cal&&(!proposal.starts_at||localDay(proposal.starts_at)!==cal.work_date)){proposal.starts_at=cal.starts_at;proposal.ends_at=cal.ends_at}})
async function mutate(body:Row){const raw=JSON.stringify(body);if(raw!==requestBody){requestKey=uuid();requestBody=raw}const result=await request('/api/use-cases/UC09',body,requestKey);requestKey='';requestBody='';return result}
async function inspectFromCalendar(id:number){scheduleView.value='records';await inspect(id);uni.pageScrollTo({scrollTop:0,duration:0})}
async function inspect(id:number){busy.value=true;error.value='';try{selected.value=await request('/api/duties/'+id)}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function startEdit(row?:Row){busy.value=true;try{error.value='';preview.value=null;draft.value=null;original.value=null;for(const key of Object.keys(decisions))delete decisions[key]
 if(row){const detail=await request('/api/duties/'+row.id);if(['draft','pending_coordination'].includes(detail.publication_state)){draft.value=detail;if(detail.replaces_duty_id)original.value=await request('/api/duties/'+detail.replaces_duty_id)}else original.value=detail;Object.assign(proposal,...fields.map(f=>({[f.key]:detail[f.key]??(f.key==='qualification_kind_ids'?[]:'')})))}
 else Object.assign(proposal,{clinic_id:initialClinic.value||work.data?.scope.clinic_id||resources.value.clinics?.[0]?.id||'',dentist_id:'',calendar_id:'',starts_at:'',ends_at:'',qualification_kind_ids:[]})
 editor.value='coordinate';dirty.value=!draft.value
 }catch(e:any){error.value=e.message}finally{busy.value=false}
}
function body(){return {...proposal,...(original.value?{original_id:original.value.id}:{}),...(draft.value?{draft_id:draft.value.id,row_version:draft.value.row_version}:{})}}
async function saveDraft(){busy.value=true;error.value='';try{for(const field of fields)if(field.required&&!proposal[field.key])throw Error('请填写'+field.label);const result=await mutate({...body(),action:'draft'});draft.value=await request('/api/duties/'+result.id);dirty.value=false;notice.value='协调稿已保存，原安排继续有效。';await loadWorkspace(true);calendarRevision.value++;await examine()}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function examine(){error.value='';const result=await request('/api/duties/preview',body());preview.value=result
 for(const a of result.affected){if(decisions[a.id]&&decisions[a.id].row_version!==a.row_version)delete decisions[a.id];if(!decisions[a.id]){const start=new Date(a.starts_at)>new Date(proposal.starts_at)?a.starts_at:proposal.starts_at;const end=new Date(new Date(start).getTime()+new Date(a.ends_at).getTime()-new Date(a.starts_at).getTime()).toISOString();decisions[a.id]={appointment_id:a.id,row_version:a.row_version,confirmation_basis:'',confirmed:false,starts_at:start,ends_at:end,operatory_id:operatories.value.find(o=>o.id===a.operatory_id)?.id||operatories.value[0]?.id||'',standard_ids:a.suggested_standard_ids}}}
}
async function publish(){if(!draft.value||dirty.value){error.value='请先保存当前协调稿，再核对影响。';return}busy.value=true;error.value='';try{await examine();const assessed=preview.value as Row|null;if(!assessed?.can_publish)throw Error(assessed?.issues.join('；')||'出诊条件尚未满足');const rows=[];for(const a of assessed.affected){if(!a.agreement_required)continue;const d=decisions[a.id];if(!d.confirmed||!d.confirmation_basis.trim())throw Error('请逐位落实患者对新安排的同意依据');if(!d.operatory_id||!d.starts_at||!d.ends_at)throw Error('请逐位确认完整时段及诊疗位');rows.push({appointment_id:a.id,row_version:d.row_version,confirmation_basis:d.confirmation_basis,replacement:{patient_id:a.patient_id,clinic_id:proposal.clinic_id,dentist_id:proposal.dentist_id,starts_at:d.starts_at,ends_at:d.ends_at,operatory_id:d.operatory_id,standard_ids:d.standard_ids,presenting_request:a.presenting_request||'按原就诊诉求安排',special_needs:a.special_needs||''}})}
 const yes=await new Promise<boolean>(resolve=>uni.showModal({title:'核对并发布出诊',content:`共${assessed.affected.length}条有效预约，${assessed.agreement_count}条涉及约定要素变化。全部校验通过后一次保存；失败保留原安排及协调稿。`,success:r=>resolve(r.confirm)}));if(!yes)return
 const result=await mutate({action:'publish-draft',draft_id:draft.value.id,row_version:draft.value.row_version,...(original.value?{original_row_version:original.value.row_version}:{}),appointment_decisions:rows});notice.value=result.replayed?'已返回首次办理记录，请核对当前状态。':'出诊已发布，约定未变的预约保持有效，已同意的新约已接续。';editor.value='';await loadWorkspace(true);calendarRevision.value++;await inspect(Number(result.id))
 }catch(e:any){error.value=e.message}finally{busy.value=false}}
async function stop(){if(!selected.value||!stopReason.value.trim()){error.value='请填写真实停诊原因。';return}const yes=await new Promise<boolean>(resolve=>uni.showModal({title:'确认实际停诊',content:'新预约将停止；受影响原约标为机构不可履行，患者可自助改约，例外事项由责任门店承接。实际已接诊记录保留。',success:r=>resolve(r.confirm)}));if(!yes)return;busy.value=true;error.value='';try{const result=await mutate({action:'stop',id:selected.value.id,row_version:selected.value.row_version,reason:stopReason.value.trim()});notice.value=result.replayed?'已返回原停诊记录，请查看当前安排。':`已登记停诊，${result.affected.length}条预约保留原记录并进入接续。`;editor.value='';await loadWorkspace(true);calendarRevision.value++;await inspect(Number(result.id))}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function saveTravel(){busy.value=true;error.value='';try{await mutate({action:'travel-rule',...travel});notice.value='转场约定已保存，发布出诊时将按方向和有效期核验。';editor.value='';await loadWorkspace(true);calendarRevision.value++}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script>
<template><WorkspaceShell title="医生与排班" active="UC09" :hide-footer="!!editor" back><view class="page-heading"><view><text class="page-title">医生与排班</text><text class="page-description">先核对营业、资格和转场，再处理预约影响。正常患者自助预约不增加人工审批。</text></view><view class="toolbar-actions"><button @click="editor='travel';error=''">转场约定</button><button class="primary" @click="startEdit()">新增出诊</button></view></view><view v-if="notice" class="notice">{{notice}}</view><view v-if="error&&!editor" class="error">{{error}}</view>
 <view class="view-tabs schedule-views" aria-label="排班视图">
  <button :class="{selected:scheduleView==='week'}" @click="scheduleView='week'">医生周排班</button>
  <button :class="{selected:scheduleView==='roster'}" @click="scheduleView='roster'">医生名录</button>
  <button :class="{selected:scheduleView==='records'}" @click="scheduleView='records'">出诊与跨店协调</button>
 </view>
 <DoctorCalendar v-if="scheduleView!=='records'" :mode="scheduleView" :revision="calendarRevision" :initial-clinic="initialClinic" :initial-cross="initialCross" @clinic="initialClinic=$event" @inspect="inspectFromCalendar"/>
 <template v-else>
 <view class="schedule-tabs view-tabs"><button v-for="item in [{id:'published',name:'已发布'},{id:'drafts',name:'待协调'},{id:'stopped',name:'已停诊'},{id:'all',name:'全部记录'}]" :key="item.id" :class="{selected:filter===item.id}" @click="filter=item.id">{{item.name}}</button><picker mode="date" :value="date||localDay()" @change="date=$event.detail.value"><button class="text-button">{{date||'筛选日期'}} <AppIcon name="calendar" :size="16"/></button></picker><button v-if="date" class="text-button" @click="date=''">清除</button></view>
 <view class="schedule-layout"><view class="duty-list"><button v-for="d in duties" :key="d.id" class="duty-line" :class="{selected:selected?.id===d.id}" @click="inspect(d.id)"><view class="duty-date"><text>{{Number(localDay(d.starts_at).slice(-2))}}</text><text>{{Number(localDay(d.starts_at).slice(5,7))}}月</text></view><view class="duty-identity"><text>{{doctorName(d.dentist_id)}} · {{clinicName(d.clinic_id)}}</text><text class="caption">{{dayLabel(d.starts_at)}} {{clock(d.starts_at)}}—{{clock(d.ends_at)}}</text></view><text class="status-label">{{format(d.publication_state)}}</text><AppIcon name="right" :size="14"/></button><view v-if="!duties.length" class="empty-state"><AppIcon name="calendar" :size="33"/><text>当前筛选下没有已读取的出诊安排。</text></view></view>
 <view v-if="selected" class="duty-detail surface"><view class="detail-title"><view><text class="section-title">{{doctorName(selected.dentist_id)}}</text><text class="caption">{{clinicName(selected.clinic_id)}} · {{dayLabel(selected.starts_at)}}</text></view><text class="status-label">{{format(selected.publication_state)}}</text></view><view class="detail-content"><text class="duty-time">{{clock(selected.starts_at)}}—{{clock(selected.ends_at)}}</text><text class="caption">{{(resources.qualification_kinds||[]).filter(q=>selected?.qualification_kind_ids.includes(q.id)).map(q=>q.qualification_name).join('、')||'资格仍按实际项目逐项校验'}}</text><view v-if="selected.stop_reason" class="attention">{{selected.stop_reason}}</view><view class="detail-actions"><button v-if="['published','stopped','draft','pending_coordination'].includes(selected.publication_state)" class="primary" @click="startEdit(selected)">{{['draft','pending_coordination'].includes(selected.publication_state)?'继续协调':selected.publication_state==='stopped'?'安排替代出诊':'协调替班或调整'}}</button><button v-if="selected.publication_state==='published'&&work.data?.scope.role_code==='manager'" class="danger" @click="editor='stop';stopReason='';error=''">登记真实停诊</button></view><text class="detail-section-title">仍需核对的有效预约 · {{selected.affected.length}}</text><view v-for="a in selected.affected" :key="a.id" class="affected-summary"><text>{{a.patient_name}}</text><text class="caption">{{clock(a.starts_at)}}—{{clock(a.ends_at)}} · {{a.operatory_name}}</text><text class="caption">{{a.appointment_no}}</text></view><text v-if="!selected.affected.length" class="caption">暂无待处理的有效预约。停诊后的原约和接续事项在预约及责任队列中保留。</text><button v-if="selected.publication_state==='stopped'&&work.data?.scope.role_code==='manager'" class="text-button" @click="goCase('UC03')">查看待重新安排的预约 <AppIcon name="right" :size="14"/></button></view></view></view>
 </template>
 <view v-if="editor" class="editor-overlay"><view class="schedule-editor" :style="nativeInsetStyle" @click.stop><view class="editor-heading"><view><text class="section-title">{{editor==='travel'?'跨店转场约定':editor==='stop'?'登记实际停诊':draft?'继续协调出诊':'出诊安排与影响协调'}}</text><text class="caption">{{editor==='coordinate'?'协调稿保留在原出诊表中，发布前不影响原约。':'按真实业务事实办理，保留原有记录。'}}</text></view><button class="icon-button" @click="editor=''" aria-label="关闭协调面板"><AppIcon name="closeempty"/></button></view><scroll-view scroll-y class="editor-scroll"><view class="editor-body"><view v-if="error" class="error">{{error}}</view>
 <template v-if="editor==='coordinate'"><view v-if="original" class="original-duty"><text class="caption">原安排 · {{format(original.publication_state)}}</text><text>{{doctorName(original.dentist_id)}} · {{clinicName(original.clinic_id)}}</text><text class="caption">{{dayLabel(original.starts_at)}} {{clock(original.starts_at)}}—{{clock(original.ends_at)}}</text></view><view class="proposal-grid"><view v-for="field in fields" :key="field.key" :class="{'full-span':field.key==='qualification_kind_ids'}"><AdcField :field="field" v-model="proposal[field.key]" :resources="formResources"/></view></view><view class="draft-controls"><button :disabled="busy" @click="saveDraft">{{busy?'核对中…':draft?'保存修改并重核影响':'保存协调稿并查看影响'}}</button><text class="caption">保存草稿不会替代已发布出诊；冲突没有解决时，可以保留协调稿继续处理。</text></view>
 <view v-if="preview" class="impact-section"><view class="impact-heading"><text class="section-title">预约影响与确认</text><text class="caption">{{preview.unchanged_count}}条约定不变 · {{preview.agreement_count}}条需逐患者落实</text></view><view v-for="issue in preview.issues" :key="issue" class="attention">{{issue}}</view><view v-for="a in preview.affected" :key="a.id" class="patient-decision"><view class="decision-heading"><view><text>{{a.patient_name}}</text><text class="caption">原约 {{dayLabel(a.starts_at)}} {{clock(a.starts_at)}}—{{clock(a.ends_at)}}</text><text class="caption">{{a.appointment_no}}</text></view><text class="status-label">{{a.agreement_required?'约定要素将变化':'原约保持有效'}}</text></view><text class="caption">{{a.requested_items.map((i:Row)=>i.request_description).join('、')||a.presenting_request}}</text><template v-if="a.agreement_required"><view class="decision-fields"><AdcField :field="{key:'starts_at',label:'患者同意的新开始时点',type:'datetime',required:true}" v-model="decisions[a.id].starts_at" :resources="formResources"/><AdcField :field="{key:'ends_at',label:'完整时段结束',type:'datetime',required:true}" v-model="decisions[a.id].ends_at" :resources="formResources"/><AdcField :field="{key:'operatory_id',label:'新诊疗位',type:'select:operatories',required:true}" v-model="decisions[a.id].operatory_id" :resources="{operatories}"/></view><view v-if="a.phase_ids.length" class="clinical-note">此预约关联治疗阶段，承接门店与先决条件仍按已确认方案核验，患者同意不能代替牙医修订计划。</view><AdcField :field="{key:'confirmation_basis',label:'患者同意及核实依据',type:'textarea',required:true}" v-model="decisions[a.id].confirmation_basis" :resources="formResources"/><view class="agreement-confirm"><switch :checked="decisions[a.id].confirmed" color="#3278cf" @change="(event:any)=>{decisions[a.id].confirmed=event.detail.value}"/><text>已向患者说明以上医生、门店及时段，并取得明确同意</text></view></template><text v-else class="unchanged-note">医生、门店和原时段均保持不变；系统仅迁移出诊引用，不另加人工审批。</text></view><view v-if="!preview.affected.length" class="inline-empty">暂无仍可履行的预约需要迁移。原出诊如已停诊，发布替代出诊后仍由患者确认新约。</view></view></template>
 <template v-if="editor==='stop'"><text class="caption">{{doctorName(selected?.dentist_id)}} · {{dayLabel(selected?.starts_at)}} {{clock(selected?.starts_at)}}—{{clock(selected?.ends_at)}}</text><view class="attention">只在原安排实际无法履行时使用。系统将阻止新预约、保留原约，并建立门店接续责任；已经接诊的事实不改为未到。</view><text class="label">真实停诊原因</text><textarea class="input" v-model="stopReason" aria-label="真实停诊原因"/></template>
 <template v-if="editor==='travel'"><AdcField v-for="field in [{key:'from_clinic_id',label:'起始门店',type:'select:clinics',required:true},{key:'to_clinic_id',label:'到达门店',type:'select:clinics',required:true},{key:'minimum_minutes',label:'最短转场时长（分钟）',type:'number',required:true},{key:'valid_from',label:'生效日期',type:'date',required:true},{key:'valid_to',label:'失效日期（选填）',type:'date',required:false},{key:'confirmation_basis',label:'时长与有效期间确认依据',type:'textarea',required:true}]" :key="field.key" :field="field" v-model="travel[field.key]" :resources="resources"/><text class="caption">方向分别保存；不能把起始到达方向的约定自动当作反向约定。</text></template>
 </view></scroll-view><view class="editor-bottom"><button :disabled="busy" @click="editor=''">返回记录</button><button class="primary" :disabled="busy||(editor==='coordinate'&&(!draft||dirty||!preview?.can_publish))" @click="editor==='coordinate'?publish():editor==='stop'?stop():saveTravel()">{{busy?'办理中…':editor==='coordinate'?'核对并发布':editor==='stop'?'确认实际停诊':'保存转场约定'}}</button></view></view></view>
